<script>
    function setTheme(themeName) {
        document.body.dataset.theme = themeName;
        localStorage.setItem('theme', themeName);
        document.querySelectorAll('.theme-button').forEach(button => {
            button.classList.remove('active');
        });
        document.getElementById(`theme-${themeName}`).classList.add('active');
    }

    function toggleMainPanel(headerElement) {
        const panel = headerElement.nextElementSibling;
        const arrow = headerElement.querySelector('.toggle-arrow');
        panel.classList.toggle('expanded');
        arrow.classList.toggle('expanded');
    }

    function selectCharacter(charId) {
        document.querySelectorAll('.avatar-container').forEach(c => {
            c.classList.toggle('active', c.id === `avatar-container-${charId}`);
            c.classList.toggle('inactive', c.id !== `avatar-container-${charId}`);
        });
        document.querySelectorAll('.character-details').forEach(p => {
            p.classList.toggle('active', p.id === `details-${charId}`);
        });
    }

    function SafeGetValue(obj, path, defaultValue = 0) {
        const value = path.split('.').reduce((acc, part) => acc && acc[part], obj);
        if (value !== undefined && value !== null && Array.isArray(value) && value.length > 0) {
            return value[0];
        }
        return defaultValue;
    }

    function updateProgressBar(barId, valueId, rawValue, min, max, color) {
        const bar = document.getElementById(barId);
        const valueText = document.getElementById(valueId);
        let numericValue = parseFloat(rawValue);

        if(isNaN(numericValue)) numericValue = min;
        numericValue = Math.max(min, Math.min(max, numericValue));

        if (valueText) {
            valueText.innerText = `${numericValue} / ${max}`;
        }

        if (bar) {
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            bar.style.width = `${percentage}%`;
            bar.style.background = typeof color === 'function' ? color(numericValue) : color;
        }
    }

    function getDiscoveryGradient(value) {
        const t = Math.min(value / 100, 1);
        const r = Math.round(135 + (220 - 135) * t);
        const g = Math.round(206 + (20 - 206) * t);
        const b = Math.round(235 + (60 - 235) * t);
        return `rgb(${r}, ${g}, ${b})`;
    }

    async function initDisplay() {
        try {
            const savedTheme = localStorage.getItem('theme') || 'light';
            setTheme(savedTheme);

            const messages = await getChatMessages(getCurrentMessageId());
            const characterData = messages?.[0]?.data?.stat_data;

            if (!characterData) {
                 document.getElementById('location-display').innerText = "无数据";
                 return;
            }

            // 更新时间和地点
            const location = SafeGetValue(characterData, '当前地点', '未知地点');
            const timeString = SafeGetValue(characterData, '当前时间', '未知时间');
            const days = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'];

            document.getElementById('location-display').innerText = location;

            const timeMatch = timeString.match(/(\d{4})年(\d{1,2})月(\d{1,2})日\s*(.*)/);
            if (timeMatch) {
                const year = parseInt(timeMatch[1], 10);
                const month = parseInt(timeMatch[2], 10) - 1;
                const day = parseInt(timeMatch[3], 10);
                const timePart = timeMatch[4];
                const dateObj = new Date(year, month, day);
                const weekday = days[dateObj.getDay()];
                document.getElementById('time-display').innerText = `${timeMatch[2]}月${timeMatch[3]}日 ${weekday} ${timePart}`;
            } else {
                 document.getElementById('time-display').innerText = timeString;
            }


            // 更新洛月数据
            if (characterData.洛月) {
                updateProgressBar('luoyue-affection-bar', 'luoyue-affection-value', SafeGetValue(characterData, '洛月.对你的好感度'), -100, 100, 'var(--accent-color-pink)');
                updateProgressBar('luoyue-discovery-bar', 'luoyue-discovery-value', SafeGetValue(characterData, '洛月.对你身份的识破度'), 0, 100, getDiscoveryGradient);
            }

            // 更新夏语冰数据
            if (characterData.夏语冰) {
                updateProgressBar('xiayubing-luoyue-affection-bar', 'xiayubing-luoyue-affection-value', SafeGetValue(characterData, '夏语冰.对洛月的好感度'), 0, 100, 'var(--accent-color-pink)');
                updateProgressBar('xiayubing-user-affection-bar', 'xiayubing-user-affection-value', SafeGetValue(characterData, '夏语冰.对你的好感度'), 0, 100, 'var(--accent-color-pink)');
            }

            // 更新容眉数据
            if (characterData.容眉) {
                updateProgressBar('rongmei-affection-bar', 'rongmei-affection-value', SafeGetValue(characterData, '容眉.对你的好感度'), -100, 100, 'var(--accent-color-pink)');
            }

            if (!document.querySelector('.avatar-container.active')) {
                selectCharacter('luoyue');
            }

        } catch (error) {
           document.getElementById('location-display').innerText = "状态加载出错";
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>

</body>
</html>
